static class WeatherViews {
 static string[] Pair(string a,string b){return new[]{a,b};}
 static Control Facts(IEnumerable<string[]> source,float font=9.5f){var values=source.ToList();var grid=Style.Grid(2,Enumerable.Repeat(-1f,values.Count).ToArray());grid.ColumnStyles[0].Width=43;grid.ColumnStyles[1].Width=57;for(int i=0;i<values.Count;i++){grid.Controls.Add(Style.Label(values[i][0],font),0,i);grid.Controls.Add(Style.Label(values[i][1],font),1,i);}return grid;}
 static Control Metric(string title,string hero,params string[][] rows){var panel=Style.Grid(1,27,42,-100);panel.BackColor=Style.Card;panel.Padding=new Padding(10,4,10,8);panel.Margin=new Padding(4);panel.Controls.Add(Style.Label(title,11,true),0,0);panel.Controls.Add(Style.Label(hero,hero.Length>20?14:hero.Length>13?18:26,true),0,1);panel.Controls.Add(Facts(rows),0,2);return panel;}
 public static Form Details(ObservingWeather w){var form=new Form();Style.Form(form);form.Text="Observing conditions & darkness";Style.FitScreen(form,1280,800);var root=Style.Grid(1,35,-100,32,38);root.Padding=new Padding(12);var nav=Style.Grid(3,-100);nav.ColumnStyles[0].SizeType=nav.ColumnStyles[1].SizeType=SizeType.Absolute;nav.ColumnStyles[0].Width=185;nav.ColumnStyles[1].Width=185;var weather=new SectionButton{Text="Conditions",Dock=DockStyle.Fill,Margin=new Padding(0,0,6,0)};var moon=new SectionButton{Text="Moon & darkness",Dock=DockStyle.Fill,Margin=new Padding(0,0,6,0)};nav.Controls.Add(weather,0,0);nav.Controls.Add(moon,1,0);nav.Controls.Add(Style.Label(w.S.Place+" · "+w.N.Time(w.N.PhaseAt),10),2,0);root.Controls.Add(nav,0,0);var host=new Panel{Dock=DockStyle.Fill,Margin=new Padding(0,5,0,0)};var conditionPage=ConditionPage(w);var moonPage=MoonPage(w);host.Controls.Add(conditionPage);host.Controls.Add(moonPage);Action<bool> show=chooseMoon=>{moonPage.Visible=chooseMoon;conditionPage.Visible=!chooseMoon;weather.Selected=!chooseMoon;moon.Selected=chooseMoon;weather.Invalidate();moon.Invalidate();};weather.Click+=(a,b)=>show(false);moon.Click+=(a,b)=>show(true);show(false);root.Controls.Add(host,0,1);root.Controls.Add(Style.Label("Open-Meteo hourly model · 7Timer seeing/transparency · means and peaks over dark hours · missing values stay unfilled",9),0,2);root.Controls.Add(Style.Button("Close",(a,b)=>form.Close()),0,3);form.Controls.Add(root);return form;}
 static Control ConditionPage(ObservingWeather w){var root=Style.Grid(1,-45,-55);var top=Style.Grid(4,-100);top.Controls.Add(Metric("CLOUD COVER",w.Value(w.Average(h=>h.Cloud),"%"),Pair("Total","Mean over dark hours"),Pair("Low",w.Value(w.Average(h=>h.LowCloud),"% mean")),Pair("Mid",w.Value(w.Average(h=>h.MidCloud),"% mean")),Pair("High",w.Value(w.Average(h=>h.HighCloud),"% mean")+" · "+w.Value(w.Peak(h=>h.HighCloud),"% peak")),Pair("Peak total",w.Value(w.Peak(h=>h.Cloud),"%"))),0,0);top.Controls.Add(Metric("WIND",w.Wind(w.Peak(h=>h.Wind)),Pair("Speed","Peak over dark hours"),Pair("Gust peak",w.Wind(w.Peak(h=>h.Gust))),Pair("Direction",w.WindDirection),Pair("Caution at",w.Wind(20)),Pair("Strong at",w.Wind(35))),1,0);top.Controls.Add(Metric("TEMP · DEW POINT",w.Temp(w.Average(h=>h.Temp)),Pair("Air","Mean over dark hours"),Pair("Dew point",w.Temp(w.Average(h=>h.Dew))),Pair("Min spread",w.Spread(w.Minimum(h=>h.Temp.HasValue&&h.Dew.HasValue?h.Temp-h.Dew:null))),Pair("Feels like",w.Temp(w.Average(h=>h.FeelsLike))),Pair("Dew risk",w.DewRisk)),2,0);top.Controls.Add(Metric("HUMIDITY",w.Value(w.Peak(h=>h.Humidity),"%"),Pair("Humidity","Peak over dark hours"),Pair("Mean",w.Value(w.Average(h=>h.Humidity),"%")),Pair("Humidity guide","≤85% planning limit"),Pair("Trend",w.Value(w.Trend(h=>h.Humidity,true),"% / hour","+0.0;-0.0;0.0")),Pair("Pressure",w.Value(w.Average(h=>h.Pressure)," hPa")),Pair("Pressure Δ",w.Value(w.Trend(h=>h.Pressure,false)," hPa / window","+0.0;-0.0;0.0"))),3,0);root.Controls.Add(top,0,0);
 var bottom=Style.Grid(2,-100);bottom.ColumnStyles[0].Width=38;bottom.ColumnStyles[1].Width=62;var site=SkySite.At(w.S);bottom.Controls.Add(Metric("SEEING · TRANSPARENCY",w.WorstSeeing.HasValue?Forecast.SeeingText(w.WorstSeeing):"Not forecast",Pair("Seeing","Worst in dark window"),Pair("Transparency",w.Transparency),Pair("Sky brightness",site?.Sqm.HasValue==true?site.Sqm.Value.ToString("0.00")+" mag/arcsec² · baseline":"Not set for this site"),Pair("Bortle",site==null?"Not set":site.Bortle.ToString("0.0")+(site.AreaEstimate?" · area estimate":" · site setting")),Pair("Moon",(w.N.Illum*100).ToString("0")+"% illuminated"),Pair("Astro dark",w.Window+" · "+w.Duration),Pair("Seeing source","7Timer ASTRO")),0,0);
 var report=Style.Grid(1,29,-100);report.Padding=new Padding(10);report.BackColor=Style.Card;report.Margin=new Padding(4);report.Controls.Add(Style.Label("FULL CONDITION REPORT · "+w.Verdict.Word,11,true),0,0);var tables=Style.Grid(2,-100);tables.Controls.Add(Facts(new[]{Pair("Cloud mean",w.Value(w.Average(h=>h.Cloud),"%")),Pair("Low / mid",w.Value(w.Average(h=>h.LowCloud),"%")+" / "+w.Value(w.Average(h=>h.MidCloud),"%")),Pair("High cloud",w.Value(w.Average(h=>h.HighCloud),"% mean")+" · "+w.Value(w.Peak(h=>h.HighCloud),"% peak")),Pair("Visibility",w.Value(w.Minimum(h=>h.Visibility).HasValue?(double?)(w.Minimum(h=>h.Visibility).Value/1000*(w.S.Fahrenheit?.621371:1)):null,w.S.Fahrenheit?" mi min":" km min")),Pair("Fog risk",w.Fog),Pair("Precipitation",w.Value(w.Hours.Any(h=>h.Precip.HasValue)?(double?)w.Hours.Where(h=>h.Precip.HasValue).Sum(h=>h.Precip.Value):null," mm (overlap hours)")),Pair("Rain chance",w.Value(w.Peak(h=>h.Rain),"% peak")),Pair("Forecast coverage",w.Hours.Count(h=>h.Cloud.HasValue)+" / "+w.Hours.Count+" dark-hour rows")}),0,0);tables.Controls.Add(Facts(new[]{Pair("Air / dew",w.Temp(w.Average(h=>h.Temp))+" / "+w.Temp(w.Average(h=>h.Dew))),Pair("Feels like",w.Temp(w.Average(h=>h.FeelsLike))),Pair("Humidity",w.Value(w.Peak(h=>h.Humidity),"% peak")),Pair("Frost potential",w.Frost),Pair("Wind speed",w.Wind(w.Peak(h=>h.Wind))+" peak"),Pair("Wind gusts",w.Wind(w.Peak(h=>h.Gust))+" peak"),Pair("Wind direction",w.WindDirection),Pair("Pressure",w.Value(w.Average(h=>h.Pressure)," hPa mean"))}),1,0);report.Controls.Add(tables,0,1);bottom.Controls.Add(report,1,0);root.Controls.Add(bottom,0,1);return root;}
 static Control Small(string heading,string value){var box=Style.Grid(1,27,-100);box.BackColor=Style.Card;box.Padding=new Padding(10);box.Margin=new Padding(4);box.Controls.Add(Style.Label(heading,9.5f,true),0,0);var label=Style.Label(value,11);label.TextAlign=ContentAlignment.TopLeft;box.Controls.Add(label,0,1);return box;}
 static Control MoonPage(ObservingWeather w){var root=Style.Grid(1,110,112,100,-100);var head=Style.Grid(2,-100);head.ColumnStyles[0].SizeType=SizeType.Absolute;head.ColumnStyles[0].Width=110;head.Controls.Add(new MoonPhaseDisk(w.N.Phase){Dock=DockStyle.Fill},0,0);head.Controls.Add(Style.Label(w.N.PhaseName()+" · "+(w.N.Illum*100).ToString("0.0")+"% illuminated\nAt mid-darkness "+w.N.Time(w.N.PhaseAt),20,true),1,0);root.Controls.Add(head,0,0);var first=Style.Grid(6,-100);var pairs=new[]{Pair("MOONRISE",w.Time(w.N.Rise)),Pair("MOONSET",w.Time(w.N.Set)),Pair("MOON-FREE WINDOW",w.MoonlessText),Pair("ASTRONOMICAL DARK",w.Window),Pair("DARK LENGTH",w.Duration),Pair("PHASE TREND",w.N.Phase<180?"Waxing":"Waning")};for(int i=0;i<pairs.Length;i++)first.Controls.Add(Small(pairs[i][0],pairs[i][1]),i,0);root.Controls.Add(first,0,1);var solar=Style.Grid(6,-100);var events=new[]{Pair("SUNSET",w.Time(w.SunEvent(CosineKitty.Direction.Set,0))),Pair("CIVIL DUSK",w.Time(w.SunEvent(CosineKitty.Direction.Set,-6))),Pair("NAUTICAL DUSK",w.Time(w.SunEvent(CosineKitty.Direction.Set,-12))),Pair("NAUTICAL DAWN",w.Time(w.SunEvent(CosineKitty.Direction.Rise,-12))),Pair("CIVIL DAWN",w.Time(w.SunEvent(CosineKitty.Direction.Rise,-6))),Pair("SUNRISE",w.Time(w.SunEvent(CosineKitty.Direction.Rise,0)))};for(int i=0;i<events.Length;i++)solar.Controls.Add(Small(events[i][0],events[i][1]),i,0);root.Controls.Add(solar,0,2);string notes=w.Moonless.Count==0&&w.DarkStart.HasValue?"The Moon is above the horizon throughout astronomical darkness. Bright Moon favors brighter objects or filtered emission targets.":"Moon-free intervals during astronomical darkness: "+w.MoonlessText+".";root.Controls.Add(Style.CardBox("MOON & DARKNESS",notes+"\n\nAstronomical darkness means Sun below −18°; civil/nautical twilight use −6°/−12°. Moon-free intervals use 10-minute altitude samples. These calculations do not include trees or terrain.",11),0,3);return root;}
 public static Form Hourly(ObservingWeather w){var form=new Form();Style.Form(form);form.Text="Tonight by hour";Style.FitScreen(form,1180,720);var root=Style.Grid(1,40,-100,43,37);root.Padding=new Padding(12);root.Controls.Add(Style.Label("Hourly forecast · "+w.Window+" · local time",17,true),0,0);var headers=new[]{"Time","Cloud","Temp ("+(w.S.Fahrenheit?"°F":"°C")+")","Dew point","Humidity","Wind ("+(w.S.Fahrenheit?"mph":"km/h")+")","Gust","Status"};int count=w.Hours.Count;var rows=new float[Math.Max(1,count)+1];rows[0]=32;for(int i=1;i<rows.Length;i++)rows[i]=-1;var table=Style.Grid(8,rows);table.Tag="hourly-table";float[] widths={16,10,11,12,10,13,12,16};for(int c=0;c<8;c++){table.ColumnStyles[c].Width=widths[c];table.Controls.Add(Style.Label(headers[c],10,true),c,0);}for(int i=0;i<count;i++){var h=w.Hours[i];var grade=ObservingWeather.Evaluate(new[]{h});string[] values={w.HourLabel(h.Utc),w.Value(h.Cloud,"%"),w.Temp(h.Temp),w.Temp(h.Dew),w.Value(h.Humidity,"%"),w.Wind(h.Wind),w.Wind(h.Gust),grade.Word};for(int c=0;c<8;c++){ConditionLevel level=c==1?Conditions.Clouds(h.Cloud):c==7?grade.Level:c==5&&h.Wind.HasValue?(h.Wind<20?ConditionLevel.Good:h.Wind<35?ConditionLevel.Medium:ConditionLevel.Poor):c==6&&h.Gust.HasValue?(h.Gust<30?ConditionLevel.Good:h.Gust<50?ConditionLevel.Medium:ConditionLevel.Poor):ConditionLevel.Unknown;var cell=new StatusText(new[]{Conditions.Row(Conditions.Value(values[c],level))},count>18?9:9.5f){Dock=DockStyle.Fill,BackColor=Style.Card,Padding=new Padding(5,count>18?1:5,0,0),Margin=count>18?new Padding(0):new Padding(0,1,0,1)};cell.AccessibleDescription=c==7?grade.Reason:headers[c];table.Controls.Add(cell,c,i+1);}}if(count==0){var blank=Style.Label("No astronomical darkness this night.",11);table.Controls.Add(blank,0,1);table.SetColumnSpan(blank,8);}root.Controls.Add(table,0,1);root.Controls.Add(Style.Label("Status is a weather planning guide using clouds, rain chance, wind/gusts, humidity and dew margin. Seeing/transparency are in Conditions.\nRows overlap the dark window; repeated local hours include UTC offsets. Missing fields show Not forecast.",9),0,2);root.Controls.Add(Style.Button("Close",(a,b)=>form.Close()),0,3);form.Controls.Add(root);return form;}
}
class MoonPhaseDisk:Control {double phase;public MoonPhaseDisk(double value){phase=value;DoubleBuffered=true;}protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Style.Bg);int size=Math.Max(8,Math.Min(Width,Height)-12);using(var image=new Bitmap(size,size)){double angle=phase*Math.PI/180;for(int y=0;y<size;y++)for(int x=0;x<size;x++){double xx=(x-size/2.0)/(size/2.0),yy=(size/2.0-y)/(size/2.0),rr=xx*xx+yy*yy;if(rr<=1){double z=Math.Sqrt(1-rr);image.SetPixel(x,y,xx*Math.Sin(angle)-z*Math.Cos(angle)>0?Style.Text:Style.DisabledBg);}else image.SetPixel(x,y,Style.Bg);}e.Graphics.DrawImageUnscaled(image,(Width-size)/2,(Height-size)/2);}}}
}
